// Renders data/projects.json (generated by scripts/build.py).
import { initFrequency } from './frequency.js';
import { LANGS, getLang, setLang, t, tCat, pick, ago, fmtDate, fmtMonth, applyStatic } from './i18n.js';

const LANG_COLORS = {
  Python: '#3572A5', TypeScript: '#3178c6', JavaScript: '#f1e05a', 'Jupyter Notebook': '#DA5B0B',
  HTML: '#e34c26', CSS: '#563d7c', SCSS: '#c6538c', 'C++': '#f34b7d', C: '#8b8b8b', Java: '#b07219',
  Kotlin: '#A97BFF', Swift: '#F05138', 'Objective-C': '#438eff', Ruby: '#b0413e', Go: '#00ADD8',
  Rust: '#dea584', MATLAB: '#e16737', Shell: '#89e051', Makefile: '#427819', Dockerfile: '#5d8494',
  HCL: '#844FBA', Dart: '#00B4AB', R: '#198CE7', Starlark: '#76d275', PLpgSQL: '#336790',
};
const CATEGORY_ORDER = ['AI & LLMs', 'Machine Learning', 'Data Engineering', 'Data Science',
  'Mobile', 'Web', 'Backend', 'Algorithms & CS', 'Python', 'Other'];

const $ = (id) => document.getElementById(id);
const state = { q: '', cat: '', stack: '', sort: 'featured', open: null, allExp: false };
const EXP_SHOWN = 4;
let DATA = null;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const fmtPct = (v) => `${v >= 10 ? Math.round(v) : Math.round(v * 10) / 10}%`;

const star = '<svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true"><path fill="currentColor" d="M8 .25a.75.75 0 0 1 .67.42l1.88 3.81 4.2.61a.75.75 0 0 1 .42 1.28l-3.04 2.96.72 4.19a.75.75 0 0 1-1.09.79L8 12.33l-3.76 1.98a.75.75 0 0 1-1.09-.79l.72-4.19L.83 6.37a.75.75 0 0 1 .42-1.28l4.2-.61L7.33.67A.75.75 0 0 1 8 .25Z"/></svg>';

// Thin segmented bar with the figures beside it (language share of the repo's code).
function langBar(langs, max = 3) {
  if (!langs?.length) return '';
  const color = (n) => LANG_COLORS[n] || '#8b8b8b';
  const shown = langs.slice(0, max);
  const rest = langs.slice(max).reduce((a, l) => a + l.pct, 0);
  return `<div class="langs">
    <div class="langbar" role="img" aria-label="${esc(langs.map((l) => `${l.name} ${l.pct}%`).join(', '))}">${
      langs.map((l) => `<span style="flex:${l.pct};background:${color(l.name)}"></span>`).join('')}</div>
    <div class="lang-legend">${shown.map((l) => `<span><i style="background:${color(l.name)}"></i>${esc(l.name)} <em>${fmtPct(l.pct)}</em></span>`).join('')}${
      rest > 0.05 ? `<span><em>+${langs.length - max} · ${fmtPct(rest)}</em></span>` : ''}</div>
  </div>`;
}

function autoBadge(p) {
  return p.summary_source === 'generated' ? `<span class="auto" title="${esc(t('autoTitle'))}">${t('auto')}</span>` : '';
}

function card(p) {
  return `<button class="card" type="button" data-name="${esc(p.name)}">
    <span class="cat">${esc(tCat(p.category))}${autoBadge(p)}</span>
    <h3>${esc(p.title)}</h3>
    <p>${esc(p.summary)}</p>
    ${langBar(p.languages)}
    <div class="card-foot">
      <span>${esc(t('updated', { ago: ago(p.updated) }))}</span>
      <span class="meta">${p.stars ? `<span>${star} ${p.stars}</span>` : ''}${p.homepage ? `<span>${t('live')}</span>` : ''}</span>
    </div>
  </button>`;
}

// ---------------------------------------------------------------------------

function renderProfile({ profile, generated_at }) {
  const headline = pick(profile.headline);
  document.title = `${profile.name} — ${headline || t('tab.projects')}`;
  $('brand').firstChild.textContent = profile.username;
  $('headline').textContent = headline ? `// ${headline}` : '';
  $('name').textContent = profile.name;
  if (profile.avatar) Object.assign($('avatar'), { src: profile.avatar, alt: profile.name, hidden: false });
  $('tagline').textContent = pick(profile.tagline);
  const links = profile.links?.length ? profile.links : [{ label: 'GitHub', url: profile.github }];
  const ext = (l, cls = '') => `<a ${cls ? `class="${cls}" ` : ''}href="${esc(l.url)}" target="_blank" rel="noopener">${esc(pick(l.label))}${cls ? ' ↗' : ''}</a>`;
  $('navLinks').innerHTML = links.map((l) => ext(l)).join('');
  $('heroCta').innerHTML = `<a class="btn primary" href="#projects" id="seeProjects">${esc(t('seeProjects'))}</a>`
    + links.map((l) => ext(l, 'btn')).join('');
  $('copyright').textContent = `© ${new Date().getFullYear()} ${profile.name}`;
  $('generated').textContent = t('synced', { ago: ago(generated_at) });
  $('langSwitch').innerHTML = LANGS.map((l) =>
    `<button type="button" data-lang="${l}" aria-pressed="${l === getLang()}">${l.toUpperCase()}</button>`).join('');
}

function renderAbout({ profile }) {
  const bio = pick(profile.about);
  const paragraphs = Array.isArray(bio) ? bio : (bio ? [bio] : []);
  const exp = profile.experience || [];
  const edu = profile.education || [];
  $('about').hidden = !paragraphs.length && !exp.length && !edu.length;
  $('bio').innerHTML = paragraphs.map((p) => `<p>${esc(p)}</p>`).join('');
  $('learningWrap').hidden = !profile.learning?.length;
  $('learning').innerHTML = (profile.learning || []).map((s) => `<span class="tag">${esc(pick(s))}</span>`).join('');

  const period = (e) => `${fmtMonth(e.start)} – ${e.end ? fmtMonth(e.end) : '…'}${e.expected ? ` (${t('expected')})` : ''}`;
  const shown = state.allExp ? exp : exp.slice(0, EXP_SHOWN);
  $('experienceWrap').hidden = !exp.length;
  $('experience').innerHTML = shown.map((e) => `<li>
      <div class="tl-head"><strong>${esc(pick(e.role))}</strong><span class="tl-date">${esc(period(e))}</span></div>
      <span class="tl-org">${esc(e.company)}</span>
      ${e.highlight ? `<p>${esc(pick(e.highlight))}</p>` : ''}
    </li>`).join('');
  $('expMore').hidden = exp.length <= EXP_SHOWN;
  $('expMore').textContent = state.allExp ? t('showLess') : t('showAllExp', { n: exp.length });

  $('educationWrap').hidden = !edu.length;
  $('education').innerHTML = edu.map((e) => `<li>
      <div class="tl-head"><strong>${esc(pick(e.degree))}</strong><span class="tl-date">${esc(period(e))}</span></div>
      <span class="tl-org">${esc(e.school)}</span>
    </li>`).join('');
}

function renderControls(projects) {
  const counts = {};
  projects.forEach((p) => { counts[p.category] = (counts[p.category] || 0) + 1; });
  const cats = Object.keys(counts).sort((a, b) => CATEGORY_ORDER.indexOf(a) - CATEGORY_ORDER.indexOf(b));
  $('categories').innerHTML = [['', t('all'), projects.length], ...cats.map((c) => [c, tCat(c), counts[c]])]
    .map(([val, label, n]) => `<button class="chip" role="tab" type="button" data-val="${esc(val)}"
      aria-selected="${state.cat === val}">${esc(label)} <small>${n}</small></button>`).join('');

  const stackCounts = {};
  projects.forEach((p) => p.stack.forEach((s) => { stackCounts[s] = (stackCounts[s] || 0) + 1; }));
  $('stackFilter').innerHTML = `<option value="">${esc(t('allTech'))}</option>` + Object.entries(stackCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([s, n]) => `<option value="${esc(s)}">${esc(s)} (${n})</option>`).join('');
  $('stackFilter').value = state.stack;
}

function filtered() {
  const q = state.q.trim().toLowerCase();
  let list = DATA.projects.filter((p) =>
    (!state.cat || p.category === state.cat) &&
    (!state.stack || p.stack.includes(state.stack)) &&
    (!q || [p.title, p.name, p.summary, p.category, tCat(p.category), ...p.stack, ...p.topics].join(' ').toLowerCase().includes(q)));
  const by = {
    updated: (a, b) => b.updated.localeCompare(a.updated),
    created: (a, b) => b.created.localeCompare(a.created),
    stars: (a, b) => b.stars - a.stars || b.updated.localeCompare(a.updated),
    name: (a, b) => a.title.localeCompare(b.title),
  }[state.sort];
  if (by) list = [...list].sort(by);
  return list;
}

function renderList() {
  const list = filtered();
  const total = DATA.projects.length;
  $('projects').innerHTML = list.map(card).join('');
  $('empty').hidden = list.length > 0;
  $('count').textContent = list.length === total ? total : t('countOf', { n: list.length, total });
  document.querySelectorAll('#categories .chip').forEach((c) =>
    c.setAttribute('aria-selected', String(c.dataset.val === state.cat)));
}

function renderFeatured() {
  const featured = DATA.projects.filter((p) => p.featured);
  $('featuredSection').hidden = !featured.length;
  $('featured').innerHTML = featured.map(card).join('');
}

// ---------------------------------------------------------------------------

function openProject(name) {
  const p = DATA.projects.find((x) => x.name === name);
  if (!p) return;
  state.open = name;
  const d = $('dialog');
  $('dCat').innerHTML = esc(tCat(p.category)) + autoBadge(p);
  $('dTitle').textContent = p.title;
  $('dSummary').textContent = p.summary;
  $('dLinks').innerHTML = [
    `<a class="btn primary" href="${esc(p.url)}" target="_blank" rel="noopener">${t('viewCode')}</a>`,
    p.homepage ? `<a class="btn" href="${esc(p.homepage)}" target="_blank" rel="noopener">${t('liveDemo')}</a>` : '',
    `<span class="meta">${esc(t('createdUpdated', { c: fmtDate(p.created), u: fmtDate(p.updated) }))}</span>`,
  ].join('');
  $('dStack').innerHTML = p.stack.map((s) => `<span class="tag">${esc(s)}</span>`).join('');
  $('dLangs').innerHTML = langBar(p.languages, 5);

  const readme = $('dReadme');
  if (p.readme) {
    readme.innerHTML = `<p class="note">${esc(t('readmeLoading'))}</p>`;
    fetch(p.readme).then((r) => (r.ok ? r.text() : Promise.reject()))
      .then((html) => { if (state.open === name) readme.innerHTML = html; })
      .catch(() => { readme.innerHTML = `<p class="note">${esc(t('readmeError'))}</p>`; });
  } else {
    readme.innerHTML = `<p class="note">${esc(t('noReadme'))}</p>`;
  }
  if (!d.open) d.showModal();
  d.querySelector('.sheet').scrollTop = 0;
  if (location.hash !== `#${encodeURIComponent(name)}`) history.replaceState(null, '', `#${encodeURIComponent(name)}`);
}

const closeDialog = () => $('dialog').close();

// ---------------------------------------------------------------------------

let freq = null;
function showTab(tab, { updateHash = true } = {}) {
  const isFreq = tab === 'frequency';
  $('panelProjects').hidden = isFreq;
  $('panelFrequency').hidden = !isFreq;
  $('tabProjects').setAttribute('aria-selected', String(!isFreq));
  $('tabFrequency').setAttribute('aria-selected', String(isFreq));
  if (isFreq && DATA && !freq) freq = initFrequency(DATA, { onPickTech: pickTech });
  else if (isFreq) freq?.refit();
  if (updateHash) history.replaceState(null, '', isFreq ? '#frequency' : location.pathname + location.search);
}

// From a Frequency bar: show the projects that use this technology.
function pickTech(tech) {
  Object.assign(state, { stack: tech, cat: '', q: '' });
  $('search').value = '';
  $('stackFilter').value = tech;
  renderList();
  showTab('projects');
  $('projectsSection').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function renderAll() {
  applyStatic();
  renderProfile(DATA);
  renderAbout(DATA);
  renderFeatured();
  renderControls(DATA.projects);
  renderList();
  freq?.render();
  if ($('dialog').open && state.open) openProject(state.open);
}

function bind() {
  document.querySelectorAll('.tab').forEach((el) => el.addEventListener('click', () => showTab(el.dataset.tab)));
  $('expMore').addEventListener('click', () => { state.allExp = !state.allExp; renderAbout(DATA); });
  $('search').addEventListener('input', (e) => { state.q = e.target.value; renderList(); });
  $('stackFilter').addEventListener('change', (e) => { state.stack = e.target.value; renderList(); });
  $('sort').addEventListener('change', (e) => { state.sort = e.target.value; renderList(); });
  $('categories').addEventListener('click', (e) => {
    const chip = e.target.closest('.chip');
    if (chip) { state.cat = chip.dataset.val; renderList(); }
  });
  $('langSwitch').addEventListener('click', (e) => {
    const b = e.target.closest('[data-lang]');
    if (!b || b.dataset.lang === getLang()) return;
    setLang(b.dataset.lang);
    renderAll();
  });
  document.addEventListener('click', (e) => {
    const c = e.target.closest('.card[data-name]');
    if (c) openProject(c.dataset.name);
    if (e.target.closest('#seeProjects')) {
      e.preventDefault();
      showTab('projects');
      $('projectsSection').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
  // README anchor links (#section) -> GitHub prefixes heading ids with "user-content-".
  $('dReadme').addEventListener('click', (e) => {
    const a = e.target.closest('a[href^="#"]');
    if (!a) return;
    e.preventDefault();
    const id = decodeURIComponent(a.getAttribute('href').slice(1));
    const target = $('dReadme').querySelector(`[id="user-content-${CSS.escape(id)}"], [id="${CSS.escape(id)}"]`);
    target?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
  $('dClose').addEventListener('click', closeDialog);
  $('dialog').addEventListener('click', (e) => { if (e.target === e.currentTarget) closeDialog(); });
  $('dialog').addEventListener('close', () => {
    state.open = null;
    if (location.hash && location.hash !== '#frequency') history.replaceState(null, '', location.pathname + location.search);
  });
}

async function init() {
  applyStatic();
  bind();
  try {
    DATA = await fetch('data/projects.json', { cache: 'no-cache' }).then((r) => r.json());
  } catch {
    $('projects').innerHTML = `<p class="empty">${esc(t('loadError'))}</p>`;
    return;
  }
  renderAll();
  const hash = decodeURIComponent(location.hash.slice(1));
  if (hash === 'frequency') showTab('frequency', { updateHash: false });
  else if (hash) openProject(hash);
}

init();
